// ─── File: TracingDemo.java ───
// Models trace-ID creation at the gateway and propagation across services.
package com.bank.gateway.demo;

import java.util.logging.*;

public class TracingDemo {
    private static final Logger log = Logger.getLogger("Tracing");
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.ALL); h.setFormatter(new TrLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Tracer tracer = new Tracer();
        Gateway gateway = new Gateway(tracer, new AccountService(tracer), new FraudService(tracer), new PaymentService(tracer));

        log.info("=== One transfer traced end to end ===");
        gateway.handleTransfer("SAV2001", "CUR3001");

        log.info("=== Assembled trace (Zipkin-style waterfall) ===");
        tracer.printWaterfall();
    }
}

// ─── Would be in tracing/TraceContext.java ───
class TraceContext {
    final String traceId;      // same for the whole request
    final String parentSpanId; // the caller's span id
    TraceContext(String traceId, String parentSpanId) {
        this.traceId = traceId; this.parentSpanId = parentSpanId;
    }
    // Serialize to a W3C traceparent header: 00-<traceId>-<spanId>-01
    String toTraceparent(String spanId) { return "00-" + traceId + "-" + spanId + "-01"; }
}

// ─── Would be in tracing/Span.java ───
class Span {
    final String service; final String spanId; final String parentSpanId; final String traceId;
    final long start; long end;
    Span(String service, String spanId, String parentSpanId, String traceId, long start) {
        this.service = service; this.spanId = spanId; this.parentSpanId = parentSpanId;
        this.traceId = traceId; this.start = start;
    }
    long durationMs() { return end - start; }
}

// ─── Would be in tracing/Tracer.java ───
class Tracer {
    private static final Logger log = Logger.getLogger("Tracing");
    private final java.util.List<Span> spans = new java.util.concurrent.CopyOnWriteArrayList<>();
    private final java.util.concurrent.atomic.AtomicInteger seq = new java.util.concurrent.atomic.AtomicInteger();

    String newId() { return String.format("%04x", seq.incrementAndGet()); }

    // Start a span under a trace context; returns a context for children.
    Span startSpan(String service, TraceContext parent) {
        String spanId = newId();
        Span span = new Span(service, spanId, parent.parentSpanId, parent.traceId, System.currentTimeMillis());
        spans.add(span);
        log.info(() -> "START span service=" + service + " traceId=" + parent.traceId
                + " spanId=" + spanId + " parent=" + parent.parentSpanId);
        return span;
    }

    void finish(Span span) { span.end = System.currentTimeMillis(); }

    TraceContext contextFor(Span span) { return new TraceContext(span.traceId, span.spanId); }

    void printWaterfall() {
        for (Span s : spans) {
            String indent = s.parentSpanId == null ? "" : "   ";
            log.info(() -> String.format("%s[%s] %-16s span=%s parent=%s %dms",
                    indent, s.traceId, s.service, s.spanId, String.valueOf(s.parentSpanId), s.durationMs()));
        }
    }
}

// ─── Would be in services/Gateway.java ───
class Gateway {
    private final Tracer tracer; private final AccountService account;
    private final FraudService fraud; private final PaymentService payment;
    Gateway(Tracer t, AccountService a, FraudService f, PaymentService p) {
        this.tracer = t; this.account = a; this.fraud = f; this.payment = p;
    }
    void handleTransfer(String from, String to) {
        // Gateway mints the trace ID (root span, no parent).
        TraceContext root = new TraceContext(tracer.newId() + tracer.newId(), null);
        Span span = tracer.startSpan("api-gateway", root);
        sleep(10);
        TraceContext ctx = tracer.contextFor(span); // propagate downstream
        account.getAccounts(from, to, ctx);
        fraud.check(from, to, ctx);
        payment.transfer(from, to, ctx);
        tracer.finish(span);
    }
    private void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); } }
}

