class AccountService {
    private final Tracer tracer;
    AccountService(Tracer t) { this.tracer = t; }
    void getAccounts(String from, String to, TraceContext ctx) {
        Span s = tracer.startSpan("account-service", ctx); sleep(40); tracer.finish(s);
    }
    private void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); } }
}

